INSERT INTO pizzas(nome_della_pizza, pizza_description, price, photo_url) VALUES('Rò', 'Variante della classica Marinara con pomodoro San Marzano, aglio fresco, origano e ingredienti speciali della casa dal gusto intenso e tradizionale.', 7.50, '/img/pizza_rò.png'),('Re', 'Pizza Regina con pomodoro, mozzarella fiordilatte, prosciutto cotto di alta qualità e basilico fresco dal gusto equilibrato e delicato.', 8.50, '/img/pizza_re.png'),('Poli', 'Pizza con polpette artigianali, salsa di pomodoro, mozzarella filante e parmigiano reggiano, ispirata alla cucina tradizionale italiana.', 9.00, '/img/pizza_poli.png'),('Oro', 'Pizza ispirata ai sapori di Napoli con pomodoro San Marzano, mozzarella premium, olio extravergine di oliva e ingredienti selezionati.', 10.00, '/img/pizza_oro.png'),('Foc', 'Focaccia semplice con olio extravergine di oliva, rosmarino fresco e sale marino croccante cotta nel forno a legna tradizionale.', 5.50, '/img/pizza_focaccia.png'),('Scl', 'Pizza Siciliana con pomodoro, mozzarella, acciughe, capperi, olive nere e origano dal gusto mediterraneo deciso e autentico.', 9.50, 'img/pizza_siciliana.png'),('Margherita', 'Pizza classica napoletana con pomodoro San Marzano, mozzarella fiordilatte fresca e basilico profumato cotta nel forno a legna.', 7.00, '/img/pizza_margherita.png'),('Marinara', 'Pizza tradizionale con pomodoro San Marzano, aglio fresco, origano e olio extravergine di oliva senza mozzarella.', 6.00, '/img/pizza_marinara.png'),('Diavola', 'Pizza con pomodoro, mozzarella filante e salame piccante italiano dal gusto forte e leggermente speziato.', 8.50, '/img/pizza_diavola.png'),('Caprese', 'Pizza ispirata alla caprese con pomodoro fresco, mozzarella di bufala, basilico e olio extravergine di oliva.', 9.00, '/img/pizza_caprese.png'),('Bufala Gourmet', 'Pizza gourmet con Mozzarella di Bufala Campana DOP, Pomodorini del Piennolo, basilico riccio fresco e olio EVO.', 12.50, '/img/pizza_bufala_gourmet.png'),('Mortadella Pistacchio', 'Pizza gourmet con stracciatella cremosa, mortadella Bologna IGP, pistacchi di Bronte e scorza di limone fresco.', 13.00, '/img/pizza_mortadella_pistacchio.png'),('Quattro Stagioni', 'Pizza con pomodoro, mozzarella, prosciutto cotto, funghi, carciofi e olive nere divisa nei quattro classici sapori.', 10.50, '/img/pizza_4_stagioni.png'),('Quattro Formaggi', 'Pizza cremosa con mozzarella, gorgonzola, fontina, parmigiano reggiano e una leggera nota di pepe nero.', 10.00, 'https://example.com/images/quattro-formaggi.jpg'),('Bufalina Doc', 'Pizza con mozzarella di bufala DOP, pomodoro San Marzano, basilico fresco e olio extravergine di oliva premium.', 11.00, 'https://example.com/images/bufalina-doc.jpg'),('Scuola Napoletana', 'Pizza napoletana con cornicione ripieno di ricotta, salame e mozzarella dal gusto ricco e tradizionale.', 13.50, 'https://example.com/images/scuola-napoletana.jpg'),('Dolce Mutiara','Pizza con pomodoro San Marzano, mozzarella fiordilatte, cipolle caramellate lentamente e pancetta croccante dal perfetto equilibrio tra dolce e saporito.',11.50,'https://example.com/images/dolce-abruzzo.jpg'),('Okonomiyaki', 'Versione ispirata alla celebre pizza giapponese con cavolo, salsa orientale, maionese giapponese e ingredienti fusion.', 11.50, 'https://example.com/images/okonomiyaki.jpg'),('Mockba', 'Pizza russa con aringa, tonno, salmone e sardine dal sapore intenso e particolare dedicata agli amanti del pesce.', 14.00, 'https://example.com/images/mockba.jpg'),('Sicario', 'Pizza-calzone leggendaria con alici saporite, scamorza affumicata e olive nere dal carattere deciso e unico.', 12.00, 'https://example.com/images/sicario.jpg'),('Abruzzese','Pizza tradizionale abruzzese con salsiccia fresca locale, scamorza affumicata e rosmarino dal gusto rustico e autentico.',10.50,'https://example.com/images/abruzzese.jpg'),('Majella','Pizza ispirata alla montagna della Majella con funghi porcini, salsiccia artigianale e mozzarella fiordilatte cremosa.',11.50,'https://example.com/images/majella.jpg'),('Trabocchi','Pizza marinara gourmet con alici dell Adriatico, pomodorini freschi, olive nere e origano selvatico abruzzese.',12.00,'https://example.com/images/trabocchi.jpg'),('Pecorara','Pizza bianca con pecorino abruzzese stagionato, miele locale e noci croccanti dal sapore equilibrato e intenso.',11.00,'https://example.com/images/pecorara.jpg'),('Contadina','Pizza rustica con patate al forno, cipolla rossa, pancetta croccante e rosmarino fresco come nelle campagne abruzzesi.',10.00,'https://example.com/images/contadina.jpg'),('Pastora','Pizza bianca con ricotta fresca di pecora, spinaci saltati e salsiccia tipica dal gusto delicato e tradizionale.',10.50,'https://example.com/images/pastora.jpg'),('Costa Adriatica','Pizza ai sapori del mare Adriatico con calamari, gamberi, prezzemolo fresco e scorza di limone.',13.50,'https://example.com/images/costa-adriatica.jpg'),('Rustichella','Pizza con ventricina piccante abruzzese, mozzarella fiordilatte e peperoni arrostiti dal carattere forte e deciso.',11.50,'https://example.com/images/rustichella.jpg'),('Gran Sasso','Pizza montanara con tartufo nero, funghi champignon e crema di pecorino ispirata ai sapori del Gran Sasso.',14.00,'https://example.com/images/gran-sasso.jpg'),('Nonna Rosa','Pizza della tradizione familiare con sugo lento di pomodoro, polpettine artigianali e basilico fresco.',11.00,'https://example.com/images/nonna-rosa.jpg'),('Ortona','Pizza bianca con tonno, cipolla caramellata, olive nere e mozzarella fresca ispirata ai sapori della costa abruzzese.',10.50,'https://example.com/images/ortona.jpg'),('Teramana','Pizza con pallottine abruzzesi, salsa di pomodoro rustica e pecorino grattugiato dal gusto ricco e casalingo.',12.00,'https://example.com/images/teramana.jpg'),('Ventricina Doc','Pizza gourmet con ventricina del Vastese, burrata fresca e miele piccante artigianale.',13.50,'https://example.com/images/ventricina-doc.jpg'),('Zafferano','Pizza bianca con crema delicata allo zafferano dell Aquila, pancetta croccante e mozzarella fiordilatte.',12.50,'https://example.com/images/zafferano.jpg'),('Pastore Abruzzese','Pizza rustica con agnello speziato, pecorino stagionato e cipolla dolce dal sapore tipico delle montagne abruzzesi.',14.50,'https://example.com/images/pastore-abruzzese.jpg'),('Costa dei Trabocchi','Pizza gourmet con burrata cremosa, alici del mare Adriatico e pomodorini confit.',13.00,'https://example.com/images/costa-dei-trabocchi.jpg'),('Montanara d Abruzzo','Pizza con patate schiacciate, salsiccia fresca, scamorza e pepe nero dal gusto intenso e contadino.',11.50,'https://example.com/images/montanara-abruzzo.jpg'),('Vecchio Mulino','Pizza tradizionale con crema di ceci, rosmarino fresco e guanciale croccante ispirata ai vecchi mulini di paese.',10.50,'https://example.com/images/vecchio-mulino.jpg'),('Vasto Marina','Pizza marinara gourmet con frutti di mare misti, aglio fresco e prezzemolo aromatico.',14.00,'https://example.com/images/vasto-marina.jpg'),('Fattoria Rosa','Pizza casereccia con mozzarella di bufala, melanzane grigliate e pomodoro rustico cotto lentamente.',11.50,'https://example.com/images/fattoria-rosa.jpg');